import{z as r,x as s,o,c,q as n,j as i,D as a,d as l,s as E,S as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"硬链接与符号链接","description":"","frontmatter":{"title":"硬链接与符号链接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hard-symlink.md","filePath":"cs/hard-symlink.md","lastUpdated":1791063341000}'),p={name:"cs/hard-symlink.md"};function A(m,e,B,h,_,k){const d=s("Mermaid");return o(),c("div",null,[e[2]||(e[2]=n('<h1 id="硬链接与符号链接" tabindex="-1">硬链接与符号链接 <a class="header-anchor" href="#硬链接与符号链接" aria-label="Permalink to &quot;硬链接与符号链接&quot;">​</a></h1><div class="epigraph"><p>硬链接是多条目录项共享同一 inode；符号链接是存路径的小文件，查找时再进入 namei。</p><footer>—— 据 Thompson, UNIX Implementation；Bach；POSIX 对 symlink 的整理</footer></div><p><a href="/cs/path-lookup">上一课</a>按分量走树。<a href="/cs/inode-dir">inode 与目录</a>已点到链接计数。缺口是把两种「多名」收成语义：硬链接不跨文件系统、对着 inode；符号链接跨文件系统、对着字符串，并有环与权限的不同规则。下一课 <a href="/cs/vfs">VFS</a> 要用统一操作表实现它们。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户希望「两个名字同一份数据」或「快捷方式指向另一路径」。若只有硬链接，挂载点对面无法指过去，目录硬链接还会制造「..」环。若只有符号链接，每次打开都依赖目标仍存在，且要决定跟随几次。缺口：<code>link</code> 增加 nlink；<code>symlink</code> 创建类型为链接的 inode，内容是路径字节；查找时对符号链接再解析，对硬链接已经在同一 inode 上结束。</p><p>本课不把 <code>readlink</code> 的全部旗标写完。</p><p><span class="marginnote">目录通常禁止硬链接（除 <code>.</code> <code>..</code>）。符号链接自身的权限往往不参与末节点访问，中间目录仍要搜权。环用跳数上限切断。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬链接：同一设备上新目录项写入已有 inode 号，nlink++。删除名字 <code>unlink</code> 减计数，到零且无打开者才回收块。符号链接：lookup 得到链接 inode，把内容当新路径（相对则相对链接所在目录）继续 <a href="/cs/path-lookup">路径查找</a>。<code>lstat</code> / <code>O_NOFOLLOW</code> 让调用者停在链接上。打开跟随链接时，末节点权限看目标 inode。</p>',9)),(o(),i(t,null,{default:a(()=>[E(d,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HARD%5B%22%E7%A1%AC%E9%93%BE%E6%8E%A5%22%5D%20--%3E%20INO%5B%22%E5%90%8C%E4%B8%80%20inode%22%5D%0A%20%20SYM%5B%22%E7%AC%A6%E5%8F%B7%E9%93%BE%E6%8E%A5%22%5D%20--%3E%20STR%5B%22%E8%B7%AF%E5%BE%84%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%0A%20%20STR%20--%3E%20NAMEI%5B%22%E5%86%8D%E6%AC%A1%20namei%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>硬链接保证「改一个名字看见的数据，另一个名字也看见」，因为没有第二份 inode。符号链接是晚绑定：目标可断（dangling），备份与跨卷引用靠它。dcache 可以缓存链接 inode，跟随仍可能未命中目标侧。不要把链接写成攻击载荷构造；只说明解析规则。</p><p><span class="marginnote">数字实例：<code>touch a</code> 后 inode 的 nlink=1；<code>ln a b</code> 变 2；<code>rm a</code> 减回 1——此时 <code>b</code> 读到的数据原封不动。若先 <code>echo x &gt; a</code>、再 <code>exec 3&lt; a</code> 后 <code>rm</code> 掉所有名字，磁盘块也要等 fd 3 关闭才回收。</span></p><p><span class="marginnote">直觉类比：硬链接像同一间房的两扇门，拆房看「门牌数」（nlink）加「屋里有没有人」（打开者）；符号链接像一张写着地址的便利贴——地址拆了它就成了断链，但便利贴本身还是完好的小文件。</span></p><p><span class="marginnote">常见误区：「rm 就是删文件」。实际 <code>rm</code> 只删目录项、把 nlink 减一；数据块要等 nlink 归零且没有进程打开这个 inode 才回收。日志被轮转脚本 unlink 后仍疯涨的「已删除文件」，就是这个机制在背锅。</span></p><p>与数据库外键无关。本栏不把关系完整性请进来。</p>',6)),(o(),i(t,null,{default:a(()=>[E(d,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20UN%5B%22unlink(%E5%90%8D%E5%AD%97)%22%5D%20--%3E%20DEC%5B%22%E8%AF%A5%20inode%20%E7%9A%84%20nlink%20%E5%87%8F%E4%B8%80%22%5D%0A%20%20DEC%20--%3E%20Z%7B%22nlink%20%3D%200%EF%BC%9F%22%7D%0A%20%20Z%20--%20%22%E5%90%A6%22%20--%3E%20KEEP%5B%22%E5%85%B6%E4%BB%96%E5%90%8D%E5%AD%97%E7%85%A7%E5%B8%B8%E8%AE%BF%E9%97%AE%E6%95%B0%E6%8D%AE%22%5D%0A%20%20Z%20--%20%22%E6%98%AF%22%20--%3E%20OP%7B%22%E8%BF%98%E6%9C%89%E8%BF%9B%E7%A8%8B%E6%89%93%E5%BC%80%E5%AE%83%EF%BC%9F%22%7D%0A%20%20OP%20--%20%22%E6%98%AF%22%20--%3E%20HOLD%5B%22%E6%95%B0%E6%8D%AE%E6%9A%82%E7%95%99%EF%BC%8Cfd%20%E5%85%A8%E5%85%B3%E5%86%8D%E5%9B%9E%E6%94%B6%22%5D%0A%20%20OP%20--%20%22%E5%90%A6%22%20--%3E%20FREE%5B%22%E5%9B%9E%E6%94%B6%20inode%20%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%9D%97%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 NTFS 交接点的对照表。不保证所有 FS 支持硬链接。下一课要把「目录、链接、设备、管道」收进同一套 inode 操作，让 <code>open</code> 不再写满分支。</p><p>后课默认：两种链接语义已定。多种文件系统如何共用 <code>read</code>/<code>lookup</code>，下一课虚拟文件系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬链接共享 inode 与 nlink；符号链接再走路径字符串。</li><li>目录硬链接默认禁止，防环。</li><li>统一操作表是 VFS 的缺口。</li><li>出处：Thompson, UNIX Implementation；Bach, <em>UNIX</em>；POSIX。</li></ul>',5))])}const f=r(p,[["render",A]]);export{u as __pageData,f as default};
